// Trap identities on the wire (#307, slot_data schema 18). Compiles the REAL
// parser (ap/ap_seedcfg.cpp is linked in) and the real tables in
// ap/ap_trap_items.h, and checks three things:
//
//   1. The shared fixture tools/fixtures/trap_identities.json (a byte-identical
//      copy of the apworld's worlds/ctr/test/fixtures/trap_identities.json)
//      matches this build row for row: enum value, effect key, item id and
//      descriptor name. Reordering the enum, the key table or the item table
//      without changing the fixture fails here.
//   2. Round trip: a slot_data generated by the apworld (seed with traps,
//      tools/fixtures/trap-identities/) parses, and every trap placed in that
//      seed resolves to the effect the fixture names.
//   3. Refusals: a pre-18 seed keeps the frozen table; a schema-18 seed with a
//      missing, malformed or newer block fires no trap; an unknown or
//      contradictory entry is refused on its own.
//
//   c++ -m32 -std=c++17 -DCTR_AP -Iap -Iap/vendor/json/include
//     tools/test-trap-identities.cpp ap/ap_seedcfg.cpp
//     -o /tmp/test-trap-identities && /tmp/test-trap-identities
//
// Run from the repository root (the fixture paths are relative to it).
// Exit 0 = every assertion held.

#include <cstdio>
#include <algorithm>
#include <cstring>
#include <fstream>
#include <string>
#include <nlohmann/json.hpp>

#include "../ap/ap_seedcfg.h"
#include "../ap/ap_trap_items.h"

extern void ap_seedcfg_parse_json(const nlohmann::json &j);

// The parser logs through the client's shim. This harness counts the
// trap_identities lines.
static int log_lines;
extern "C" void AP_LogLine(const char *line)
{
	if (std::strstr(line, "trap_identities"))
		log_lines++;
}

static int checks;
static int failures;

static void expect(bool ok, const std::string &name)
{
	checks++;
	if (!ok)
	{
		failures++;
		std::printf("FAIL %s\n", name.c_str());
	}
}

static nlohmann::json load(const char *path)
{
	std::ifstream in(path);
	if (!in)
	{
		std::printf("FAIL cannot open %s\n", path);
		failures++;
		return nlohmann::json::object();
	}
	return nlohmann::json::parse(in);
}

// Enum names, so the fixture's native_effect text maps to this build's value.
#define T(x) {#x, x}
static const struct
{
	const char *name;
	int value;
} ENUM_NAMES[] = {
	T(AP_TRAP_ICY), T(AP_TRAP_LOWGRAV), T(AP_TRAP_USF_NOBRAKE), T(AP_TRAP_BOOST),
	T(AP_TRAP_FIRSTPERSON), T(AP_TRAP_WUMPA_WIPEOUT), T(AP_TRAP_FLATTEN),
	T(AP_TRAP_ITEM_REROLL), T(AP_TRAP_FORCED_USE), T(AP_TRAP_EMPTY_CRATES),
	T(AP_TRAP_WEAKENED_KART), T(AP_TRAP_BOOST_BLOCKER), T(AP_TRAP_WIREFRAME),
	T(AP_TRAP_NITRO), T(AP_TRAP_REVERSE_STEERING), T(AP_TRAP_RED_POTION),
	T(AP_TRAP_UPSIDE_DOWN), T(AP_TRAP_MIRROR_MODE), T(AP_TRAP_WARPBALL_AMBUSH),
	T(AP_TRAP_DEMO_CAMERA), T(AP_TRAP_CLOCKED_OUT), T(AP_TRAP_REVERSE_CAMERA),
};
#undef T

static int enum_value(const std::string &name)
{
	for (const auto &e : ENUM_NAMES)
		if (name == e.name)
			return e.value;
	return -1;
}

static int resolve_id(long long id)
{
	return AP_TrapResolveEffect(&ctr_trap_identities, id - AP_TRAP_ITEM_ID_BASE);
}

static nlohmann::json seed18(const nlohmann::json &items)
{
	nlohmann::json d = {{"ctr_options", {{"schema_version", 18}}}};
	d["trap_identities"] = {{"version", 1}, {"items", items}};
	return d;
}

int main()
{
	const nlohmann::json fx = load("tools/fixtures/trap_identities.json");
	const nlohmann::json &rows = fx["traps"];

	// ── 1. the fixture against this build ──
	expect(fx["version"] == AP_TRAP_IDENTITIES_VERSION, "fixture version is the block version");
	expect((int)rows.size() == AP_TRAP_EFFECT_COUNT, "one fixture row per AP_TrapEffect");
	expect((int)rows.size() == AP_TRAP_ITEM_MAP_COUNT, "one fixture row per trap item");
	for (int e = 0; e < AP_TRAP_EFFECT_COUNT; e++)
		expect(AP_TRAP_EFFECT_KEY[e] != 0, "every effect has a key");
	for (size_t i = 0; i < rows.size(); i++)
	{
		const std::string key = rows[i]["key"];
		const std::string where = " (row " + std::to_string(i) + " " + key + ")";
		const long long id = rows[i]["item_id"];
		const int e = enum_value(rows[i]["native_effect"]);
		expect(e == (int)i, "fixture row index is the enum value" + where);
		if (e < 0)
			continue;
		expect(std::strcmp(AP_TRAP_EFFECT_KEY[e], key.c_str()) == 0, "effect key matches" + where);
		expect(AP_TrapEffectForKey(key.c_str()) == e, "key resolves to the effect" + where);
		expect(AP_TrapEffectForItemId(id) == e, "item table maps the id to the effect" + where);
		expect(rows[i]["name"] == AP_TRAP_DESC[e].name, "descriptor name matches" + where);
	}
	expect(AP_TrapEffectForKey("future_unknown_trap") == -1, "a key this build lacks is unknown");

	// ── 2. round trip through a generated seed ──
	const nlohmann::json sd = load("tools/fixtures/trap-identities/seed_slot_data.json");
	const nlohmann::json placed = load("tools/fixtures/trap-identities/seed_placed_traps.json")["placed"];
	log_lines = 0;
	ap_seedcfg_parse_json(sd);
	expect(ctr_cfg.schema_version == 18, "generated seed is schema 18 and admitted");
	expect(ctr_cfg.schema_newer == 0, "schema 18 is not newer than this build");
	expect(ctr_trap_identities.required == 1, "schema 18 requires the block");
	expect(ctr_trap_identities.state == AP_TRAP_IDS_VALID, "generated block accepted");
	expect(placed.size() >= 10, "the seed places traps of many kinds");
	for (const auto &p : placed)
	{
		const long long id = p;
		int want = -1;
		for (size_t i = 0; i < rows.size(); i++)
			if (rows[i]["item_id"] == id)
				want = enum_value(rows[i]["native_effect"]);
		expect(want >= 0 && resolve_id(id) == want,
		       "placed trap " + std::to_string(id) + " resolves to its fixture effect");
		std::printf("  %lld -> %s\n", id, want >= 0 ? AP_TRAP_EFFECT_KEY[want] : "?");
	}
	for (size_t i = 0; i < rows.size(); i++) {
        const auto id=rows[i]["item_id"].get<long long>();
        expect(resolve_id(id)==(sd["trap_identities"]["items"].contains(std::to_string(id))?(int)i:-1),
               "older schema-18 seed resolves only its declared traps");
    }
    const auto clocked=load("tools/fixtures/trap-identities/clocked_out.json");
    ap_seedcfg_parse_json(clocked["slot_data"]);
    for(size_t i=0;i<rows.size();++i)
        expect(resolve_id(rows[i]["item_id"])==(int)i,"new generated seed resolves all appended trap identities");
    expect(std::find(clocked["drawn_trap_ids"].begin(),clocked["drawn_trap_ids"].end(),35010206)!=clocked["drawn_trap_ids"].end(),
           "real generator drew the minted Clocked Out item");

	// ── 3. refusals and the legacy path ──
	nlohmann::json legacy = sd;
	legacy["schema_version"] = 16;
	legacy["ctr_options"]["schema_version"] = 16;
	legacy.erase("trap_identities");
	ap_seedcfg_parse_json(legacy);
	expect(ctr_trap_identities.required == 0, "a schema-16 seed does not require the block");
	for (size_t i = 0; i < rows.size(); i++)
		expect(resolve_id(rows[i]["item_id"]) == (int)i, "a schema-16 seed uses the frozen table");

	ap_seedcfg_parse_json(nlohmann::json::object());
	expect(ctr_trap_identities.required == 0 && resolve_id(35010016) == AP_TRAP_ICY,
	       "no slot_data keeps the frozen table");

	nlohmann::json missing = sd;
	missing.erase("trap_identities");
	log_lines = 0;
	ap_seedcfg_parse_json(missing);
	expect(ctr_trap_identities.state == AP_TRAP_IDS_INVALID, "schema 18 without the block is refused");
	expect(log_lines == 1, "a refused block logs one line");
	expect(resolve_id(35010016) == -1 && resolve_id(35010193) == -1, "a refused block fires no trap");

	nlohmann::json newer = sd;
	newer["trap_identities"]["version"] = 2;
	ap_seedcfg_parse_json(newer);
	expect(ctr_trap_identities.state == AP_TRAP_IDS_INVALID, "an unknown block version is refused");

	nlohmann::json bad = sd;
	bad["trap_identities"]["items"] = nlohmann::json::array();
	ap_seedcfg_parse_json(bad);
	expect(ctr_trap_identities.state == AP_TRAP_IDS_INVALID, "items that is not a map is refused");

	// One contradiction (icy_road named for the Low Gravity item), one unknown
	// key on a known item, one unknown item id, one non-numeric id; the rest
	// stay usable.
	log_lines = 0;
	ap_seedcfg_parse_json(seed18({{"35010016", "icy_road"},
	                              {"35010017", "icy_road"},
	                              {"35010019", "clocked_out"},
	                              {"35010194", "clocked_out"},
	                              {"icy", "icy_road"},
	                              {"35010193", "demo_camera"}}));
	expect(ctr_trap_identities.state == AP_TRAP_IDS_VALID, "a block with bad entries is still read");
	expect(log_lines == 5, "one log line per refused entry plus the summary (got " +
	                           std::to_string(log_lines) + ")");
	expect(resolve_id(35010016) == AP_TRAP_ICY, "an agreed entry fires");
	expect(resolve_id(35010193) == AP_TRAP_DEMO_CAMERA, "an agreed entry fires (demo camera)");
	expect(resolve_id(35010017) == -1, "a contradictory entry is refused");
	expect(resolve_id(35010019) == -1, "an unknown key is refused");
	expect(resolve_id(35010020) == -1, "a trap the seed did not name is refused");

	std::printf("%d checks, %d failures\n", checks, failures);
	return failures ? 1 : 0;
}
